//! Checks for the lesson 02 lab. Do not edit this file.
//!
//! The functions call the C library through *your* `fletch-sys` declarations.
//! The tests compare the answers with checksums computed in Rust.

/// Fletcher-16 through the C library.
pub fn checksum16(data: &[u8]) -> u16 {
    // SAFETY: `data` is readable for `data.len()` bytes, and the C function
    // does not read the pointer when the length is 0.
    unsafe { fletch_sys::fletch16(data.as_ptr(), data.len()) }
}

/// Fletcher-32 through the C library.
#[cfg(feature = "wide")]
pub fn checksum32(data: &[u8]) -> u32 {
    // SAFETY: as in `checksum16`.
    unsafe { fletch_sys::fletch32(data.as_ptr(), data.len()) }
}

/// Whether the linked C library was compiled with `FLETCH_WIDE`.
pub fn has_wide() -> bool {
    // The block is needed if the declaration is a plain `fn`, and harmless if
    // it is a `safe fn`.
    #[allow(unused_unsafe)]
    // SAFETY: the function has no arguments and no preconditions.
    let wide = unsafe { fletch_sys::fletch_has_wide() };
    wide != 0
}

/// The path of fletch.h, as `fletch-sys` announced it to this crate's build script.
pub fn header_path() -> &'static str {
    env!("CHECKER_FLETCH_HEADER")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rust16(data: &[u8]) -> u16 {
        let (mut a, mut b) = (0u32, 0u32);
        for &byte in data {
            a = (a + u32::from(byte)) % 255;
            b = (b + a) % 255;
        }
        ((b << 8) | a) as u16
    }

    #[test]
    fn fletch16_matches_known_values() {
        assert_eq!(checksum16(b"abcde"), 0xC8F0);
        assert_eq!(checksum16(b"abcdef"), 0x2057);
        assert_eq!(checksum16(b"abcdefgh"), 0x0627);
        assert_eq!(checksum16(b""), 0, "an empty slice has checksum 0");
    }

    #[test]
    fn fletch16_matches_a_rust_implementation() {
        let data: Vec<u8> = (0..=999u32).map(|n| (n * 7 % 256) as u8).collect();
        for end in [1, 2, 255, 256, 1000] {
            assert_eq!(
                checksum16(&data[..end]),
                rust16(&data[..end]),
                "first {end} bytes"
            );
        }
    }

    #[test]
    fn the_header_was_announced_to_dependents() {
        let text = std::fs::read_to_string(header_path()).expect("fletch.h is readable");
        assert!(
            text.contains("fletch16"),
            "{} is not the fletch header",
            header_path()
        );
    }

    #[cfg(not(feature = "wide"))]
    #[test]
    fn default_build_has_no_wide_checksum() {
        assert!(
            !has_wide(),
            "FLETCH_WIDE must be defined only when the `wide` feature is on"
        );
    }

    #[cfg(feature = "wide")]
    #[test]
    fn wide_feature_defines_fletch_wide() {
        assert!(
            has_wide(),
            "with the `wide` feature, build.rs must define FLETCH_WIDE for the C compiler"
        );
        assert_eq!(checksum32(b"abcde"), 0xF04F_C729);
        assert_eq!(checksum32(b"abcdef"), 0x5650_2D2A);
        assert_eq!(checksum32(b"abcdefgh"), 0xEBE1_9591);
        assert_eq!(checksum32(b""), 0);
    }
}
